"""Summarize reproducible geometric and comparative FEA checks without certifying strength."""
import json,hashlib,pathlib,html
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from .model import ROOT
OUT=ROOT/'output/rigid-base2';A=OUT/'analysis'
def main():
    supports={n:json.loads((A/(n+'-supports.json')).read_text()) for n in ['before','after']}
    fe={n:{str(h):json.loads((A/f'{n}-h{h}.json').read_text()) for h in [6,4,3]} for n in ['before','after']}
    prior=json.loads((ROOT/'rigid_base2/reference/v41-analysis.json').read_text())
    for n in fe:
        digest=hashlib.sha256((A/(n+'.step')).read_bytes()).hexdigest()
        for h,r in fe[n].items():
            assert r['step_sha256']==digest
            assert all(c['linear_residual']<1e-6 for c in r['cases'])
    assert supports['after']['stl_sha256']==hashlib.sha256((OUT/'STL/Cylindrical_Z_support.stl').read_bytes()).hexdigest()
    assert not supports['after']['large_overhang_layers'] and not supports['after']['floating_regions']
    labels={'radial_10N':'Radial / X, 10 N','normal_10N':'Toward rear / Y, 10 N','payload_20N_150mm':'20 N downward + 3 N·m pitch','yaw_1Nm':'Yaw torque, 1 N·m'}
    cases=[]
    for i,name in enumerate(labels):
        before=fe['before']['3']['cases'][i];after=fe['after']['3']['cases'][i]
        conv={n:abs(fe[n]['3']['cases'][i]['largest_mount_displacement_mm']-fe[n]['4']['cases'][i]['largest_mount_displacement_mm'])/fe[n]['3']['cases'][i]['largest_mount_displacement_mm'] for n in fe}
        cases.append(dict(case=name,label=labels[name],before_mm=before['largest_mount_displacement_mm'],after_mm=after['largest_mount_displacement_mm'],reduction_fraction=1-after['largest_mount_displacement_mm']/before['largest_mount_displacement_mm'],change_4_to_3_mm_mesh=conv,after_peak_element_centroid_von_mises_MPa=after['peak_von_mises_MPa']))
    manifest=json.loads((OUT/'print-manifest.json').read_text());vol=next(r['volume_mm3'] for r in manifest if r['name']=='Cylindrical_Z_support')
    incremental=[]
    for i,name in enumerate(labels):
        reductions={str(h):1-fe['after'][str(h)]['cases'][i]['largest_mount_displacement_mm']/prior['finite_element_runs'][str(h)]['cases'][i]['largest_mount_displacement_mm'] for h in [6,4,3]}
        incremental.append(dict(case=name,label=labels[name],prior_mm=prior['finite_element_runs']['3']['cases'][i]['largest_mount_displacement_mm'],after_mm=fe['after']['3']['cases'][i]['largest_mount_displacement_mm'],reduction_by_mesh=reductions))
    sources=['rigid_base2/model.py','rigid_base2/check.py','rigid_base2/support_analysis.py','rigid_base2/structural_analysis.py','rigid_base2/analysis_report.py']
    summary=dict(passed=True,analysis_completed=True,physical_strength_verified=False,mesh_converged=False,safety_factor=None,baseline_commit='ae030ba5f96ead0a6d8c920f3017ae50577215e0',effective_E_MPa=1000,poisson_ratio=.35,material='Unspecified filament and infill: assumed homogeneous effective E=1 GPa. Displacements scale inversely with E.',grid_rear_connections='Two 6 mm diagonal perforated shear webs, from grid X=±62 to rear columns near X=±38, with full-height root contact.',support_area_reduction_fraction=1-supports['after']['steep_downward_surface_area_mm2']/supports['before']['steep_downward_surface_area_mm2'],solid_volume_mm3=vol,baseline_solid_volume_mm3=1049361.193725947,cases=cases,supports=supports,finite_element_runs=fe,conclusions=[],source_sha256={n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest() for n in sources},input_sha256={n:hashlib.sha256((A/n).read_bytes()).hexdigest() for n in ['before.step','after.step','before.stl','after.stl']})
    summary.update(material='PETG intended; wall count, infill and layer bonding unspecified. Assumed homogeneous effective E=1 GPa, not a measured PETG value or guaranteed lower bound. Displacements scale inversely with E.',rear_cross_panel='6 mm transverse perforated panel at Y=-104, joining the two rear webs and cylindrical wall.',prior_revision=prior,incremental_cases=incremental)
    summary['source_sha256']['rigid_base2/reference/v41-analysis.json']=hashlib.sha256((ROOT/'rigid_base2/reference/v41-analysis.json').read_bytes()).hexdigest()
    summary['conclusions']=[f"{r['label']}: {100*min(r['reduction_by_mesh'].values()):.1f}–{100*max(r['reduction_by_mesh'].values()):.1f}% less predicted mount movement than v41 across tested meshes." for r in incremental]+['All-direction improvement is a comparative trend, not a converged absolute stiffness or strength result.','No safety factor, vibration performance or probing accuracy is certified. PETG print and joint behavior are unmeasured.','The upright geometric layer audit finds no floating regions or large unsupported growth. Short mounting-hole bridges still require slicer/print verification.']
    (OUT/'analysis-validation.json').write_text(json.dumps(summary,indent=2))
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False})
    fig,ax=plt.subplots(1,2,figsize=(10,3.7),layout='constrained')
    ax[0].bar(['Before','Revised'],[supports[n]['steep_downward_surface_area_mm2']/100 for n in ['before','after']],color=['#9aa5af','#577eae']);ax[0].set_ylabel('Steep downward-facing area (cm²)');ax[0].set_title('Upright print geometry')
    for title,runs,c in [('Original',fe['before'],'#9aa5af'),('Previous cage',prior['finite_element_runs'],'#c68758'),('Rear cross-panel',fe['after'],'#577eae')]:
        ax[1].plot([6,4,3],[runs[str(h)]['cases'][0]['largest_mount_displacement_mm'] for h in [6,4,3]],'o-',label=title,color=c)
    ax[1].invert_xaxis();ax[1].set_xlabel('Nominal tetrahedral mesh size (mm)');ax[1].set_ylabel('Largest mount displacement (mm)');ax[1].set_title('10 N radial · assumed E = 1 GPa');ax[1].legend();fig.savefig(A/'comparison.png',dpi=150);plt.close(fig)
    fig,axes=plt.subplots(1,2,figsize=(8,4),layout='constrained');vmax=0
    data={}
    for n in ['before','after']:
        f=np.load(A/f'{n}-h3-fields.npz');p=f['points'];u=np.linalg.norm(f['radial_10N'],axis=1);mask=(abs(p[:,1]+42)<1e-4)&(p[:,2]>=226)&(abs(p[:,0])<104);data[n]=(p[mask],u[mask]);vmax=max(vmax,float(u[mask].max()))
    for ax,n in zip(axes,['before','after']):
        p,u=data[n];im=ax.scatter(p[:,0],p[:,2],c=u,s=7,vmin=0,vmax=vmax,cmap='viridis');ax.set_title(n.capitalize());ax.set_xlabel('X (mm)');ax.set_ylabel('Z (mm)');ax.set_aspect('equal')
    fig.colorbar(im,ax=axes,label='Mounting-face displacement magnitude (mm)');fig.suptitle('10 N radial · 3 mm mesh · E = 1 GPa\nOriginal vs. cross-panel cage; absolute values not mesh-converged',fontsize=11);fig.savefig(A/'displacement.png',dpi=150);plt.close(fig)
    rows=''.join(f"<tr><td>{html.escape(c['label'])}</td><td>{c['before_mm']:.3f}</td><td>{c['after_mm']:.3f}</td><td>{100*c['reduction_fraction']:.1f}%</td></tr>" for c in cases)
    sensitivity=''.join(f"<tr><td>{html.escape(c['label'])}</td><td>{100*c['change_4_to_3_mm_mesh']['before']:.1f}%</td><td>{100*c['change_4_to_3_mm_mesh']['after']:.1f}%</td></tr>" for c in cases)
    incremental_rows=''.join(f"<tr><td>{html.escape(c['label'])}</td><td>{c['prior_mm']:.3f}</td><td>{c['after_mm']:.3f}</td><td>{100*min(c['reduction_by_mesh'].values()):.1f}–{100*max(c['reduction_by_mesh'].values()):.1f}%</td></tr>" for c in incremental)
    doc=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Cage support and structural analysis</title><style>body{{max-width:940px;margin:30px auto;padding:0 20px;font:16px/1.6 system-ui;color:#243441;background:#f6f8fa}}a{{color:#356d95}}img{{max-width:100%;background:white}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{padding:9px;border-bottom:1px solid #ccd5dd;text-align:left}}h1,h2{{line-height:1.25}}.note{{padding:14px;background:#e4edf3;border-left:4px solid #577eae}}</style><a href="../../../rigid-base2.html">← Rigid Base 2</a><h1>Support and structural analysis</h1><p>The revised cage connects the grid directly to the rear columns through two broad, perforated 6 mm webs. Angled webs land near existing mounting bolts. A new 6 mm transverse rear panel ties both webs to the cylindrical wall and resists radial sway. It has four large peaked apertures. Four clipped column remnants are removed. Peaked window roofs and 45° flange undersides reduce support demand.</p><p class="note">This is a geometric print audit and comparative linear-elastic FEA. It does not certify strength, probing accuracy or vibration performance. Absolute FEA results are not mesh-converged.</p><h2>Print supports</h2><p>The actual bed-oriented STLs were compared at 0.2 mm layer height, with a nominal 45° growth allowance plus 0.035 mm numerical tolerance. Steep downward-facing area falls <strong>{100*summary['support_area_reduction_fraction']:.1f}%</strong>, from {supports['before']['steep_downward_surface_area_mm2']:.0f} to {supports['after']['steep_downward_surface_area_mm2']:.0f} mm². The final audit found zero floating regions and zero large-overhang layers. The largest sampled distance to previous-layer material is {supports['after']['max_sampled_distance_to_previous_layer_mm']:.1f} mm, versus {supports['before']['max_sampled_distance_to_previous_layer_mm']:.1f} mm before.</p><p>Print upright on the bottom flange. The main cage windows and rear-web windows now use sloped roofs. Small horizontal mounting holes still need short bridges. Inspect these and roof seams in the H2S slicer; add localized support if its preview or a bridge test calls for it. This analysis does not generate G-code or calculate slicer support mass.</p><img src="comparison.png" alt="Overhang area and mesh sensitivity comparison"><h2>Structural comparison</h2><p>PETG is the intended material. Wall count, infill and layer bonding remain unspecified; this is an assumed effective stiffness, not a measured PETG value or a guaranteed lower bound.</p><p>Assumed homogeneous effective modulus: <strong>1,000 MPa</strong>; Poisson ratio 0.35. The ten bottom bolt-pad regions are clamped to an ideal rigid deck. Loads are distributed over the four actuator mounting regions. No screw slip, insert compliance, infill topology, layer anisotropy, creep or fatigue is modeled.</p><p>These are specified comparison loads, not measured operating loads. The payload case is 20 N downward plus a 3 N·m pitch moment (150 mm offset). The figures below are largest average mount-patch movement from the finest tested linear-tetrahedral mesh.</p><h3>Against the original cage (ae030ba)</h3><table><tr><th>Load case</th><th>Original (mm)</th><th>Revised (mm)</th><th>Reduction</th></tr>{rows}</table><h3>What the new rear cross-panel adds</h3><p>This comparison is against the previously published rear-web cage (f7c03c8, Site v41). The table uses the 3 mm mesh for displacement and all three meshes for the reduction range.</p><table><tr><th>Load case</th><th>Previous cage (mm)</th><th>Cross-panel (mm)</th><th>Reduction across meshes</th></tr>{incremental_rows}</table><p>The cross-panel predicts less movement in every tested load case across all three meshes. This consistent direction of change supports retaining it, but the magnitude remains uncertain because absolute results are not mesh-converged. No vibration or settling-time claim is made.</p><img src="displacement.png" alt="Mounting-face displacement under the radial load"><h2>Numerical limits and remaining weaknesses</h2><p>Nominal mesh sizes 6, 4 and 3 mm were tested. All linear solves passed residual and force-balance checks. The 4-to-3 mm change below shows why the absolute numbers must not be used as accuracy promises or a safety factor.</p><table><tr><th>Load case</th><th>Before sensitivity</th><th>Revised sensitivity</th></tr>{sensitivity}</table><p>Radial and torsional compliance still need physical measurement. Printed layer bonding, joint movement and the real deck can add deflection beyond this idealized model. Sharp-edge/constraint stress peaks are mesh-sensitive, and no material strength allowable was supplied, so no strength pass/fail or safety factor is claimed. For an effective modulus of 0.5–2 GPa, calculated displacement scales from twice to half the tabulated values.</p><p>Modeled solid volume is {vol/1000:.0f} cm³ versus 1049 cm³ before ({100*(vol/1049361.193725947-1):.1f}% increase). Compared with the previous rear-web cage ({prior['solid_volume_mm3']/1000:.0f} cm³), the cross-panel adds {100*(vol/prior['solid_volume_mm3']-1):.1f}% solid volume. The added material is concentrated in the rear load paths, transverse panel and sloped flanges. Filament use depends on slicing.</p><h2>Reproduce and verify</h2><p><a href="../analysis-validation.json">Full numerical report and input/source hashes</a> · <a href="https://github.com/tscircuit/probe-robot-arm/tree/main/rigid_base2">Scripts and baseline geometry</a>. The study uses <a href="https://gmsh.info/doc/texinfo/">Gmsh</a> for tetrahedral meshing and the <a href="https://scikit-fem.readthedocs.io/en/stable/listofexamples.html">scikit-fem linear-elasticity formulation</a>. Baseline is source commit ae030ba.</p><p>Before relying on the cage for probing, measure mount/probe displacement and settling under known loads in radial, rear-directed and twisting directions. A physical bridge test and slicer preview are still needed.</p></html>'''
    (A/'report.html').write_text(doc);print('Analysis report written; mesh convergence is explicitly NOT claimed')
if __name__=='__main__':main()
